test('logout during note save preflight prevents writes',async t=>{const s=await noteEditSetup(t),review=JSON.parse((await s.prepare()).body);let release;s.api.getPrivateNoteForEdit=()=>new Promise(resolve=>release=resolve);const pending=s.save(review.reviewId);while(!release)await new Promise(resolve=>setImmediate(resolve));await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([s.row]);assert.equal((await pending).status,409);assert.equal(s.writes,0);});
