test('later searches invalidate older task actions and pending completion reviews',async t=>{const s=await actionableTaskSearch(t),row=JSON.parse((await s.search()).body).results[0];let release;s.api.getPrivateTask=()=>new Promise(resolve=>release=resolve);const pending=call(s.router,'/auth/workspace/tasks/review',{method:'POST',headers:s.headers,body:{completionToken:row.completionToken}});while(!release)await new Promise(resolve=>setImmediate(resolve));await s.search();release([s.row]);assert.equal((await pending).status,409);s.token=row.editToken;assert.equal((await s.prepare()).status,409);assert.equal(s.writes,0);});
test('search cannot invalidate a task edit already being saved',async t=>{const s=await actionableTaskSearch(t),row=JSON.parse((await s.search()).body).results[0];s.token=row.editToken;const review=JSON.parse((await s.prepare()).body);let release,calls=0;const read=s.api.getPrivateTask;s.api.getPrivateTask=(...args)=>++calls===1?new Promise(resolve=>release=resolve):read(...args);const pending=s.save(review.reviewId);while(!release)await new Promise(resolve=>setImmediate(resolve));assert.equal((await s.search()).status,409);release([structuredClone(s.row)]);assert.equal((await pending).status,200);assert.equal(s.writes,1);});

async function appearanceSetup(t){const s=await setup(t,{allowBriefRead:true,allowAppearance:true});s.appearanceReads=0;s.row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',version:1,deleted_at:null,...makeBriefPreferencesRecord({palette:'coastal',density:'compact'},owner)};s.row.payload.secret='NEVER_RETURN_APPEARANCE';s.api.listPrivateAppearance=async()=>{s.appearanceReads++;return[s.row];};s.brief=()=>call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});return s;}
test('saved appearance is opt-in and returned only after verified login without unrelated settings',async t=>{const s=await appearanceSetup(t);assert.equal((await s.brief()).status,401);assert.equal(s.appearanceReads,0);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});const result=await s.brief();assert.equal(result.status,200);assert.equal(JSON.parse(result.body).appearance.palette,'coastal');assert.equal(JSON.parse(result.body).appearance.readOnly,true);assert.equal(s.appearanceReads,1);assert.doesNotMatch(result.body,/NEVER_RETURN_APPEARANCE|bbbbbbbb|quietHours|navigation/);});
test('appearance read outage uses an explicit default without blocking verified Brief records',async t=>{const s=await appearanceSetup(t);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});s.api.listPrivateAppearance=async()=>{throw Error('Fictional unavailable appearance');};const result=await s.brief();assert.equal(result.status,200);assert.equal(JSON.parse(result.body).appearance.available,false);assert.equal(JSON.parse(result.body).appearance.palette,'neutral');});
test('foreign appearance or sign-out during its read cannot leak display settings',async t=>{for(const mode of ['foreign','logout']){const s=await appearanceSetup(t);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});let release;s.api.listPrivateAppearance=()=>new Promise(resolve=>release=resolve);const pending=s.brief();while(!release)await new Promise(resolve=>setImmediate(resolve));if(mode==='logout')await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});else s.row.owner_id='cccccccc-cccc-4ccc-8ccc-cccccccccccc';release([s.row]);const result=await pending;assert.equal(result.status,503);assert.doesNotMatch(result.body,/coastal|compact|bbbbbbbb|NEVER_RETURN/);}});
